using Avalonia.Controls;
using Microsoft.Extensions.DependencyInjection;
using XnaReborn.App.Services;
using XnaReborn.App.ViewModels;

namespace XnaReborn.App;

/// <summary>
/// The composition root: every service and view model is registered here. Screen workers do not edit this file.
/// Page view models are singletons, so <see cref="MainViewModel.CurrentPage"/> and a direct request return the same object.
/// </summary>
public static class AppServices
{
    /// <summary>Builds the container for the running app and checks every registration.</summary>
    /// <param name="topLevel">Returns the main window, which owns dialogs and the clipboard, or null before it exists.</param>
    public static ServiceProvider Build(Func<TopLevel?> topLevel)
    {
        ArgumentNullException.ThrowIfNull(topLevel);
        var services = new ServiceCollection();
        services.AddSingleton(topLevel);
        services.AddSingleton<IAnalysisService>(_ => new AnalysisService());
        services.AddSingleton<IMigrationService, MigrationService>();
        services.AddSingleton<IRunService, RunService>();
        services.AddSingleton<IDialogService>(p => new DialogService(p.GetRequiredService<Func<TopLevel?>>()));
        services.AddSingleton<IClipboardService>(p => new ClipboardService(p.GetRequiredService<Func<TopLevel?>>()));
        services.AddSingleton<IRecentProjectsStore>(_ => new RecentProjectsStore());
        services.AddSingleton<IShellService, ShellService>();
        AddViewModels(services);
        return services.BuildServiceProvider(new ServiceProviderOptions { ValidateOnBuild = true, ValidateScopes = true });
    }

    /// <summary>Registers the session, <see cref="INavigator"/>, <see cref="MainViewModel"/> and the six page view models. Tests reuse this with fake services.</summary>
    /// <param name="services">The collection to add to.</param>
    public static IServiceCollection AddViewModels(IServiceCollection services)
    {
        ArgumentNullException.ThrowIfNull(services);
        services.AddSingleton<WorkflowSession>();
        services.AddSingleton<MainViewModel>();
        services.AddSingleton<INavigator>(p => p.GetRequiredService<MainViewModel>());
        services.AddSingleton<OpenProjectViewModel>();
        services.AddSingleton<ReportViewModel>();
        services.AddSingleton<MigrationSetupViewModel>();
        services.AddSingleton<DiffViewModel>();
        services.AddSingleton<BuildRunViewModel>();
        services.AddSingleton<SummaryViewModel>();
        return services;
    }
}
